  Definition pf_rs (w : Z) : list (word * Z) :=
    [(Z_to_bv 64 (bv_unsigned sp0 - 208 - 1056), 1056%Z); (Z_to_bv 64 0xb94a8, 4%Z); (Z_to_bv 64 0xb94d0, 8%Z); (Z_to_bv 64 w, 2%Z)].
  Definition CPpf (w : Z) (a : Z) : Prop :=
    (~ (bv_unsigned sp0 - 208 - 1056 <= a < bv_unsigned sp0 - 208) /\ ~ (0xb94a8 <= a < 0xb94ac) /\ ~ (0xb94d0 <= a < 0xb94d8) /\ ~ (w <= a < w + 2))%Z.
  Definition SCpf (a : Z) : Prop := (bv_unsigned sp0 - 208 - 1056 <= a < bv_unsigned sp0 - 208)%Z.

